// RemoveTeamWorkspaceTeams relationships from objects passed in.
// Removes related items from R.TeamWorkspaceTeams (uses pointer comparison, removal does not keep order)
// Sets related.R.GrantMCPConnectionGrants.
func (o *MCPConnectionGrant) RemoveTeamWorkspaceTeams(ctx context.Context, exec boil.ContextExecutor, related ...*WorkspaceTeam) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	query := fmt.Sprintf(
		"delete from \"mcp_connection_grant_teams\" where \"grant_id\" = $1 and \"team_id\" in (%s)",
		strmangle.Placeholders(dialect.UseIndexPlaceholders, len(related), 2, 1),
	)
	values := []any{o.ID}
	for _, rel := range related {
		values = append(values, rel.ID)
	}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err = exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}
	removeTeamWorkspaceTeamsFromGrantMCPConnectionGrantsSlice(o, related)
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.TeamWorkspaceTeams {
			if rel != ri {
				continue
			}

			ln := len(o.R.TeamWorkspaceTeams)
			if ln > 1 && i < ln-1 {
				o.R.TeamWorkspaceTeams[i] = o.R.TeamWorkspaceTeams[ln-1]
			}
			o.R.TeamWorkspaceTeams = o.R.TeamWorkspaceTeams[:ln-1]
			break
		}
	}

	return nil
}

